var list_services_default = defineTool({
  name: "list_services",
  title: "Listar servi\xE7os",
  description: "Lista o cat\xE1logo p\xFAblico de servi\xE7os de assist\xEAncia t\xE9cnica oferecidos (slug, t\xEDtulo, resumo e palavras-chave). Use para descobrir quais servi\xE7os existem antes de pedir detalhes.",
  inputSchema: {
    search: z.string().trim().optional().describe("Filtro opcional por texto no t\xEDtulo, descri\xE7\xE3o ou palavras-chave.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ search }) => {
    const term = search?.toLowerCase();
    const items = Object.values(servicesData).map((s) => ({
      slug: s.slug,
      title: s.title,
      subtitle: s.subtitle,
      description: s.description,
      keywords: s.keywords,
      url: `https://precisodeumtecnico.com/servicos/${s.slug}`
    })).filter(
      (s) => !term ? true : [s.title, s.subtitle, s.description, s.keywords.join(" ")].join(" ").toLowerCase().includes(term)
    );
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { count: items.length, services: items }
    };
  }
});

