import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.26.3";
import { z as z2 } from "npm:zod@^3.24.2";
var get_service_default = defineTool2({
  name: "get_service",
  title: "Detalhes de um servi\xE7o",
  description: "Retorna os detalhes p\xFAblicos completos de um servi\xE7o: descri\xE7\xE3o longa, benef\xEDcios, o que est\xE1 incluso, etapas do processo, faixas de pre\xE7o de tabela e FAQ.",
  inputSchema: {
    slug: z2.string().trim().describe("Slug do servi\xE7o, por exemplo 'informatica'. Use list_services para descobrir.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug }) => {
    const service = servicesData[slug.toLowerCase()];
    if (!service) {
      return {
        content: [
          {
            type: "text",
            text: `Servi\xE7o '${slug}' n\xE3o encontrado. Slugs v\xE1lidos: ${Object.keys(servicesData).join(", ")}`
          }
        ],
        isError: true
      };
    }
    const payload = {
      slug: service.slug,
      title: service.title,
      subtitle: service.subtitle,
      description: service.description,
      longDescription: service.longDescription,
      benefits: service.benefits,
      includedServices: service.includedServices,
      process: service.process,
      pricing: service.pricing,
      faqs: service.faqs,
      relatedServices: service.relatedServices,
      keywords: service.keywords,
      url: `https://precisodeumtecnico.com/servicos/${service.slug}`
    };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: { service: payload }
    };
  }
});

