var getEnabledNationalCities = () => nationalCities.filter((c2) => c2.enabled !== false);
var getCityBairroSlugs = (citySlug) => (nationalBairrosByCity[citySlug] ?? []).map((b) => b.slug);

// src/lib/mcp/tools/list-coverage.ts
var list_coverage_default = defineTool4({
  name: "list_coverage",
  title: "Cobertura de atendimento",
  description: "Lista as \xE1reas atendidas: cidades de atendimento direto em Curitiba e Regi\xE3o Metropolitana (com bairros) e as cidades da rede nacional de prestadores parceiros.",
  inputSchema: {
    scope: z3.enum(["curitiba", "nacional", "todos"]).optional().describe("Escopo da cobertura. Padr\xE3o: 'todos'."),
    city: z3.string().trim().optional().describe("Filtro opcional por nome ou slug de cidade.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ scope = "todos", city }) => {
    const term = city?.toLowerCase();
    const matches = (name, slug) => !term || name.toLowerCase().includes(term) || slug.toLowerCase().includes(term);
    const regional = scope === "nacional" ? [] : getAllCities().filter((c2) => matches(c2.name, c2.slug)).map((c2) => ({
      name: c2.name,
      slug: c2.slug,
      isMainCity: c2.isMainCity,
      neighborhoods: c2.neighborhoods,
      url: `https://precisodeumtecnico.com/regioes/${c2.slug}`
    }));
    const national = scope === "curitiba" ? [] : getEnabledNationalCities().filter((c2) => matches(c2.name, c2.slug)).map((c2) => ({
      name: c2.name,
      slug: c2.slug,
      uf: c2.uf,
      region: c2.region,
      type: c2.type,
      neighborhoodSlugs: getCityBairroSlugs(c2.slug),
      url: `https://precisodeumtecnico.com/atendimento-nacional/${c2.slug}`
    }));
    const payload = {
      directService: {
        label: "Atendimento direto \u2014 Curitiba e Regi\xE3o Metropolitana",
        cities: regional
      },
      partnerNetwork: {
        label: "Rede nacional de prestadores parceiros",
        disclaimer: "Parceiros podem praticar termos, condi\xE7\xF5es, valores e prazos diferentes.",
        cities: national
      }
    };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: payload
    };
  }
});

