// src/lib/mcp/tools/list-faqs.ts
var list_faqs_default = defineTool5({
  name: "list_faqs",
  title: "Perguntas frequentes",
  description: "Retorna as perguntas frequentes p\xFAblicas do site sobre atendimento, prazos, garantia, or\xE7amento e formas de pagamento.",
  inputSchema: {
    search: z4.string().trim().optional().describe("Filtro opcional por texto na pergunta ou resposta.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ search }) => {
    const term = search?.toLowerCase();
    const items = homeFaqs.filter(
      (f) => !term ? true : `${f.question} ${f.answer}`.toLowerCase().includes(term)
    );
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { count: items.length, faqs: items }
    };
  }
});

